import{_ as o,l as n,o as e,c as l,v as t,p,x as i,d as s,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"CMOS 反相器为什么成对","description":"","frontmatter":{"title":"CMOS 反相器为什么成对","date":"2026-09-10T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/cmos-inverter-pair.md","filePath":"litho/cmos-inverter-pair.md","lastUpdated":1789023840000}'),d={name:"litho/cmos-inverter-pair.md"};function S(m,a,_,E,M,O){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="cmos-反相器为什么成对" tabindex="-1">CMOS 反相器为什么成对 <a class="header-anchor" href="#cmos-反相器为什么成对" aria-label="Permalink to &quot;CMOS 反相器为什么成对&quot;">​</a></h1><div class="epigraph"><p>CMOS 用互补的 nMOS 与 pMOS 接成反相器：一个导通时另一个关断，静态几乎无直流通路，输出仍能满摆幅。</p><footer>—— 据 Sze &amp; Ng, Physics of Semiconductor Devices 对 CMOS 反相器与互补逻辑的整理</footer></div><p><a href="/litho/mosfet-gate-length">上一课</a>钉死了单管 MOSFET 与栅长。本课不重推短沟道效应。缺口是：芯片逻辑不是单个晶体管。为何必须同时有 n 沟道与 p 沟道、因而必须有两套掺杂区与隔离图形？这决定前道有多少层必须被画出来。一种导电类型做不出静态近零功耗的逻辑族，图形化必须为两种沟道分区。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只有一种 <a href="/litho/mosfet-gate-length">MOSFET</a> 也能做开关，但负载要么常耗电，要么噪声容限差。NMOS 逻辑的静态功耗在集成度上去之后不可接受。CMOS 的答案是成对：输入低则 n 管关、p 管开，输出高；输入高则相反。缺口是「成对」对图形化的含义——阱、有源区、隔离各占一块必须用掩模定义的区域——不是再解释一次栅控沟道。一种导电类型做不出静态近零功耗的逻辑族。</p><h3 id="成对不是把同一根栅画两次" tabindex="-1">成对不是把同一根栅画两次 <a class="header-anchor" href="#成对不是把同一根栅画两次" aria-label="Permalink to &quot;成对不是把同一根栅画两次&quot;">​</a></h3><p>n 管与 p 管可以共用同一层栅图形（多晶硅或金属栅跨过不同阱），但有源区类型、阱类型、阈值注入往往是不同的掩模。成对指电路拓扑与掺杂分区，不是「曝光两次同一根线」。把 CMOS 理解成双重曝光，会与后课真正的多重图形化撞名。</p><p><span class="marginnote">反相器是最小静态 CMOS 单元。NAND、NOR 仍是上拉网络与下拉网络成对。电源与地的引出已经要求接触孔，那是后课；本课先把分区画出来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>CMOS 反相器：pMOS 源接 \\(V_{\\mathrm{DD}}\\)，nMOS 源接地，两栅相连为输入，两漏相连为输出。静态时总有一管截止，电源到地没有直流通路。翻转瞬间两管可能短暂同时导通，尺寸比用来平衡上升与下降，本课不把尺寸优化做完。</p><p>只有 nMOS 加电阻负载也能反相，但静态电流在亿只管子上不可接受——这是成对存在的电路理由，图形化只是把这个理由落实到硅上。p 管要做在 n 阱里、n 管在 p 型衬底（或双阱），两套掺杂不能靠「同一层栅」自动出现。每一套都要一次图形选择。本课把理由钉在反相器上；单元库里更复杂的门只是同一成对原则的重复。</p><p>图形化清单因此至少包括：阱（定衬底类型）、有源区（定哪里有源漏）、栅（定 \\(L\\) 与逻辑连接）、隔离（定晶体管彼此分开）。每一项都是一次图形定义加后续工艺。没有这些分区，互补对无法同时做在同一块硅上。</p><p><span class="marginnote">p 管与 n 管的迁移率不同，反相器尺寸比常让 p 管更宽。那是 \\(W\\) 的图形，不是再要一根栅。本课成对指导电类型，宽度比是版图细节。</span></p>',13)),(e(),p(c,null,{default:i(()=>[h(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20NMOS%5B%22nMOS%20%E4%B8%8B%E6%8B%89%22%5D%20--%3E%20INV%5B%22%E5%8F%8D%E7%9B%B8%E5%99%A8%22%5D%0A%20%20PMOS%5B%22pMOS%20%E4%B8%8A%E6%8B%89%22%5D%20--%3E%20INV%0A%20%20INV%20--%3E%20STATIC%5B%22%E9%9D%99%E6%80%81%E8%BF%91%E9%9B%B6%E7%9B%B4%E6%B5%81%22%5D%0A%20%20INV%20--%3E%20MASK%5B%22%E9%98%B1%E3%80%81%E6%9C%89%E6%BA%90%E3%80%81%E6%A0%85%E3%80%81%E9%9A%94%E7%A6%BB%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>互补是 CMOS 成为主流的原因：密度上升后，不能再用常开负载换逻辑。光刻任务因此不仅是「把栅印细」，还要在同一套套刻预算下对准阱、有源与栅——后课 <a href="/litho/contact-via-line">接触孔、通孔与线</a> 再把竖直连接补上。本课先回答：为什么图形是分区的，而不只是一根线。</p><p>阱与有源的交界还决定闩锁与隔离能否成立：n 阱与 p 阱必须被图形化分开，否则互补对在硅里短路。隔离槽本身也是一层图形。于是「成对」在版图上是一串必须对齐的多边形，不是电路图上的两个符号而已。</p><p>下一课 <a href="/litho/interconnect-halfpitch">互连半节距与金属层</a> 指出：即便栅已经做成，门与门之间还要金属线，横向尺度会从栅转到节距。成像如何印这些线，仍不属于本课程。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开传输门、FinFET 的鳍片布局或背面供电。不写光刻胶、照明与分辨率公式。也不把「成对」推广成所有电路都必须 n/p 数量相等——那是单元库设计，本课只要反相器这一最小理由。</p><p>动态逻辑、传输门会少用一半管子，但主流标准单元仍是静态 CMOS，图形化清单仍按互补对准备。后课默认：静态 CMOS 逻辑建立在互补对上；前道必须图形化阱、有源、栅与隔离。下一课只补互连节距。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CMOS 反相器用 nMOS 下拉、pMOS 上拉，静态近零直流功耗。</li><li>成对要求阱与有源等分区，各自由图形化定义。</li><li>成对不是同一根栅曝光两次；多重图形化是后课另一件事。</li><li>栅细之外，套刻要把这些分区对齐。</li><li>只有 nMOS 加负载也能反相，但静态电流在高集成度下不可接受，这是成对的电路理由。</li><li>出处：Sze &amp; Ng, <em>Physics of Semiconductor Devices</em>。</li></ul>',9))])}const B=o(d,[["render",S]]);export{u as __pageData,B as default};
